// Turn the account data into a clear answer for the agent
const j = $json;

if (!j || !j.full_name) {
  return { json: { result: 'NOT VERIFIED. The customer ID or security answer did not match. Do not share any account information. Ask the caller to verify again.' } };
}

// Helpers
const list = v => (typeof v === 'string' ? JSON.parse(v) : v) || [];

// Spell out a dollar amount the way people say it out loud
const spokenMoney = n => {
  const ones = ['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];
  const tens = ['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];
  const under1000 = x => {
    const parts = [];
    if (x >= 100) { parts.push(ones[Math.floor(x / 100)] + ' hundred'); x %= 100; }
    if (x >= 20) { parts.push(tens[Math.floor(x / 10)] + (x % 10 ? '-' + ones[x % 10] : '')); }
    else if (x > 0 || parts.length === 0) { parts.push(ones[x]); }
    return parts.join(' ');
  };
  const words = x => {
    if (x === 0) return 'zero';
    const groups = [[1e9, 'billion'], [1e6, 'million'], [1e3, 'thousand']];
    const parts = [];
    for (const [size, name] of groups) {
      if (x >= size) { parts.push(under1000(Math.floor(x / size)) + ' ' + name); x %= size; }
    }
    if (x > 0) parts.push(under1000(x));
    return parts.join(' ');
  };
  const total = Math.round(Math.abs(Number(n)) * 100);
  const dollars = Math.floor(total / 100);
  const cents = total % 100;
  let s = `${words(dollars)} dollar${dollars === 1 ? '' : 's'}`;
  if (cents) s += ` and ${words(cents)} cent${cents === 1 ? '' : 's'}`;
  return s;
};

// Every amount appears as a number AND in words, e.g. "$25.00 (twenty-five dollars)"
// Amounts in words first (to be spoken), with the number in brackets
const money = n => (n === null || n === undefined) ? 'unknown'
  : `${spokenMoney(n)} (${Number(n).toLocaleString('en-US', { style: 'currency', currency: 'USD' })})`;

const date = d => {
  if (!d) return 'unknown';
  const dt = new Date(String(d).slice(0, 10) + 'T12:00:00Z');
  return dt.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
};
const cap = s => s ? s.charAt(0).toUpperCase() + s.slice(1) : s;

const lines = [];
lines.push(`ACCOUNT OVERVIEW for verified customer ${j.full_name}, customer ID ${j.customer_id}.`);
lines.push('Answer only from this data. Share only what the caller asked about, not the whole list. Do not calculate new numbers yourself.');

if (j.kyc_status && j.kyc_status !== 'verified') {
  lines.push(`Identity documents (KYC) status: ${j.kyc_status}. Search policies for what this means if relevant.`);
}

// Accounts
const accounts = list(j.accounts);
lines.push('', 'ACCOUNTS:');
if (!accounts.length) lines.push('- No accounts.');
let total = 0;
for (const a of accounts) {
  const bal = Number(a.balance);
  total += bal;
  let s = `- ${cap(a.type)} account ending ${a.last4}: balance ${money(bal)}`;
  if (bal < 0) s += ` (overdrawn by ${money(-bal)})`;
  s += `, status ${a.status}`;
  if (a.status_reason) s += ` (reason: ${a.status_reason})`;
  if (a.type === 'checking') s += `, overdraft limit ${money(a.overdraft_limit)}`;
  if (a.type === 'savings') s += `, interest rate ${Number(a.interest_rate)} percent per year`;
  lines.push(s + '.');
}
if (accounts.length > 1) lines.push(`- Total across all accounts: ${money(total)}.`);

// Cards
const cards = list(j.cards);
lines.push('', 'CARDS:');
if (!cards.length) lines.push('- No cards.');
for (const k of cards) {
  let s = `- ${cap(k.type)} card ending ${k.last4}: status ${k.status}, expires ${date(k.expiry)}`;
  if (k.type === 'debit') s += `, daily spending limit ${money(k.daily_limit)}`;
  if (k.type === 'credit') {
    s += `, credit limit ${money(k.credit_limit)}, outstanding balance ${money(k.outstanding)}`;
    s += `, available credit ${money(Number(k.credit_limit) - Number(k.outstanding))}`;
    s += `, minimum payment ${money(k.minimum_payment)} due ${date(k.payment_due)}`;
  }
  lines.push(s + '.');
}

// Loans
const loans = list(j.loans);
lines.push('', 'LOANS:');
if (!loans.length) lines.push('- No loans.');
for (const l of loans) {
  let s = `- ${cap(l.type)} loan: status ${l.status}`;
  if (l.status === 'paid_off') {
    s += ', fully repaid';
  } else {
    s += `, monthly payment ${money(l.monthly_payment)}, remaining balance ${money(l.remaining_balance)}`;
    s += `, interest rate ${Number(l.interest_rate)} percent`;
    if (l.status === 'late') s += `, LATE: ${l.days_past_due} days past due, the missed payment was due ${date(l.next_due_date)}`;
    else s += `, next payment due ${date(l.next_due_date)}`;
  }
  lines.push(s + '.');
}

// Transfers
const transfers = list(j.transfers);
lines.push('', 'TRANSFERS IN THE LAST 60 DAYS:');
if (!transfers.length) lines.push('- No transfers.');
for (const t of transfers) {
  let s = `- ${cap(t.type)} transfer of ${money(t.amount)} to ${t.beneficiary} at ${t.bank}, sent ${date(t.initiated)}: status ${t.status}`;
  if (Number(t.fee) > 0) s += `, fee ${money(t.fee)}`;
  if (t.status === 'processing') s += `, expected to complete ${date(t.expected)}`;
  if (t.failure_reason) s += ` (reason: ${t.failure_reason})`;
  lines.push(s + '.');
}

// Tickets
const tickets = list(j.open_tickets);
lines.push('', 'OPEN SUPPORT TICKETS:');
if (!tickets.length) lines.push('- No open tickets.');
for (const tk of tickets) {
  lines.push(`- Ticket number ${tk.ticket_id} (${tk.category}), opened ${date(tk.created)}, status ${tk.status}: ${tk.description}`);
}

return { json: { result: lines.join('\n') } };
